    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst15100.tx_fnSearch_ajaxsubmit" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_searchCorpGroupList_rawxhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_searchCorpGroupList_rawxhr = async function () {
    const sbmOptions = {
        id: "tx_searchCorpGroupList_rawxhr",
        method: "post",
        action: "/corpgeneral/corpGroup.do?method=searchCorpGroupList&corpGroupType=",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jlddst15100.tx_searchCorpGroupList_rawxhr" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fnOrder
 * @author Inswave
 * @date 2026. 09. 29
 * @param mode stat
 * @returns
 * @hidden N
*/
scwin.fnOrder = async function (mode, stat) {
    /* sdd-asis-lifecycle:begin fnOrder — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent("dma_fnDownloadReq").set("orderMode", mode);
    $c.util.getComponent("dma_fnDownloadReq").set("orderStat", stat);
    $("#searchForm > #pageIndex").val("1");
    await scwin.fnSearch();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearch
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnSearch = async function () {
    /* sdd-asis-lifecycle:begin fnSearch — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const titleofaccnt = scwin.makeTitleOfAccountParamString();
    $c.util.getComponent('ipt_titleofaccnt').setValue(titleofaccnt);
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchFinancialInfoInCorpGroup");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "list");
    await scwin.tx_fnSearch_ajaxsubmit();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnSearchCallBack1
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.fnSearchCallBack1 = function (data) {
    /* sdd-asis-lifecycle:begin fnSearchCallBack1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $("#mainContents").empty().append(data);
    console.warn('[sdd] 미실현(재설계 분류 #128): fnLegendTooltip(' + "" + ')');
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeTitleOfAccountPanel
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeTitleOfAccountPanel = function () {
    /* sdd-asis-lifecycle:begin changeTitleOfAccountPanel — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const val = $c.util.getComponent('slc_fininfotype').getValue();
    if (val === "finstat") {
        scwin.title_of_account1.setStyle("display", "");
        scwin.title_of_account2.setStyle("display", "none");
        $c.util.getComponent('ipt_finsearchtype').setValue("finstat");
        $c.util.getComponent("dma_fnDownloadReq").set("orderMode", scwin.finstat[0]);
        $c.util.getComponent("dma_fnDownloadReq").set("orderStat", 'D');
    } else {
        if (val === "finrate") {
            scwin.title_of_account1.setStyle("display", "none");
            scwin.title_of_account2.setStyle("display", "");
            $c.util.getComponent('ipt_finsearchtype').setValue("finrate");
            $c.util.getComponent("dma_fnDownloadReq").set("orderMode", scwin.finrate[0]);
            $c.util.getComponent("dma_fnDownloadReq").set("orderStat", 'D');
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.makeTitleOfAccountParamString
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.makeTitleOfAccountParamString = function () {
    /* sdd-asis-lifecycle:begin makeTitleOfAccountParamString — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    var paramString = "";
    let flag = false;
    var paramString = "";
    const finsearchtype = $c.util.getComponent('ipt_finsearchtype').getValue();
    if (finsearchtype === "finstat") {
        for (var i = 0; i < scwin.finstat.length; i++) {
            flag = scwin.checkChkBoxStatus(scwin.finstat[i]);
            if (flag) {
                paramString += scwin.finstat[i];
                if (i !== (scwin.finstat.length - 1)) {
                    paramString += "|";
                }
            }
        }
    } else {
        if (finsearchtype === "finrate") {
            for (var i = 0; i < scwin.finrate.length; i++) {
                flag = scwin.checkChkBoxStatus(scwin.finrate[i]);
                if (flag) {
                    paramString += scwin.finrate[i];
                    if (i !== (scwin.finrate.length - 1)) {
                        paramString += "|";
                    }
                }
            }
        }
    }
    return paramString;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.checkChkBoxStatus
 * @author Inswave
 * @date 2026. 09. 29
 * @param id
 * @returns
 * @hidden N
*/
scwin.checkChkBoxStatus = function (id) {
    /* sdd-asis-lifecycle:begin checkChkBoxStatus — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    return $("#" + id).is(":checked");
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.searchCorpGroupList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.searchCorpGroupList = async function () {
    /* sdd-asis-lifecycle:begin searchCorpGroupList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const gubun = "2";
    await scwin.tx_searchCorpGroupList_rawxhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.handleStateChange
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.handleStateChange = function () {
    /* sdd-asis-lifecycle:begin handleStateChange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (scwin.xmlHttp.readyState == 4) {
        if (scwin.xmlHttp.status == 200) {
            scwin.updateCorpGroupList();
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.updateCorpGroupList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.updateCorpGroupList = function () {
    /* sdd-asis-lifecycle:begin updateCorpGroupList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const element = scwin.xmlHttp.responseXML;
    const nodeList = element.getElementsByTagName("item");
    let node = null;
    let name = null;
    let value = null;
    const objSelect = $("#searchForm").find("select[name=slc_groupCd]");
    for (let i = 0; i < nodeList.length; i++) {
        node = nodeList[i];
        name = node.getElementsByTagName("name")[0].firstChild.nodeValue;
        value = node.getElementsByTagName("value")[0].firstChild.nodeValue;
        const objOption = $("<option />");
        objOption.val(name);
        objOption.html(value);
        objSelect.append(objOption);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.createXMLHttpRequest
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.createXMLHttpRequest = function () {
    /* sdd-asis-lifecycle:begin createXMLHttpRequest — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.xmlHttp = null;
    if (XMLHttpRequest) {
        scwin.xmlHttp = new XMLHttpRequest();
    }
    return scwin.xmlHttp;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.changeAllCheckState
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.changeAllCheckState = function () {
    /* sdd-asis-lifecycle:begin changeAllCheckState — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const val = $c.util.getComponent('slc_fininfotype').getValue();
    if (val === "finstat") {
        for (var i = 0; i < scwin.finstat.length; i++) {
            if ($("#ipt_chAll1").is(":checked")) {
                $("#" + scwin.finstat[i]).attr("checked", true);
            } else {
                $("#" + scwin.finstat[i]).attr("checked", false);
            }
        }
    } else {
        if (val === "finrate") {
            for (var i = 0; i < scwin.finrate.length; i++) {
                if ($("#ipt_chAll2").is(":checked")) {
                    $("#" + scwin.finrate[i]).attr("checked", true);
                } else {
                    $("#" + scwin.finrate[i]).attr("checked", false);
                }
            }
        }
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const titleofaccnt = scwin.makeTitleOfAccountParamString();
    $c.util.getComponent('ipt_titleofaccnt').setValue(titleofaccnt);
    $c.util.getComponent("dma_fnDownloadReq").set("method", "download_corpgroup");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "download_corpgroup");
    await scwin.tx_fnDownload();
    /* sdd-asis-lifecycle:end */
};
